let mypageInlineRefreshPromise = null;
let mypageInlineRefreshSession = null;
async function refreshMypageInlineData() {
  if (mypageInlineRefreshPromise && authRequestSessionCurrent(mypageInlineRefreshSession)) return mypageInlineRefreshPromise;
  const session = authRequestSession();
  const pending = Promise.all([loadMypageSummary(), loadMypageSettings(), loadActivationProgress()])
    .then(() => { if (authRequestSessionCurrent(session)) initMypageTabs(); })
    .finally(() => {
      if (mypageInlineRefreshPromise === pending) {
        mypageInlineRefreshPromise = null;
        mypageInlineRefreshSession = null;
      }
    });
  mypageInlineRefreshSession = session;
  mypageInlineRefreshPromise = pending;
  return pending;
}
